<script setup>import { Head,Link } from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; defineProps({course:Object}); const labels={DRAFT:'پیش‌نویس',PUBLISHED:'منتشرشده',INACTIVE:'غیرفعال'};</script>
